import ast,re,duckdb
pat1=[r'(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},\s*(\d{4})', r'(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{4})', r'\b(19\d{2}|20\d{2})\b']
def first_year(s):
    if not s: return None
    for pat in pat1:
        m=re.search(pat,s,re.I)
        if m: return int(m.group(1))
    return None
def idkey(s): return int(re.search(r'(\d+)$',s).group(1))
con=duckdb.connect(':memory:')
con.execute("SET memory_limit='1GB'")
con.execute("SET extension_directory='/home/exedev/.duckdb/extensions'")
con.execute('LOAD sqlite_scanner'); con.execute('LOAD postgres_scanner')
con.execute("ATTACH '/workspace/query_dataset/review_query.db' AS review_db (TYPE sqlite, READ_ONLY)")
con.execute("ATTACH 'host=dab-postgres port=5432 dbname=bookreview_db user=postgres password=postgres' AS books_db (TYPE postgres, READ_ONLY)")
parsed=[]; fallbacks=[]
for book_id,title,categories,details,features in con.execute('SELECT book_id,title,categories,details,features FROM books_db.books_info').fetchall():
    y=first_year(details); source='details'
    if y is None:
        y=first_year(features); source='features'
    if y is None:
        y=first_year(title); source='title'
    if source!='details' and y is not None: fallbacks.append((book_id,title,y,source))
    parsed.append((idkey(book_id),book_id,title,ast.literal_eval(categories) if categories else [],y,(y//10)*10 if y else None))
con.execute('CREATE TEMP TABLE b(book_key int, book_id varchar, title varchar, categories varchar[], pub_year int, decade_start int)')
con.executemany('INSERT INTO b VALUES (?, ?, ?, ?, ?, ?)', parsed)
con.execute("CREATE TEMP TABLE r AS SELECT regexp_extract(purchase_id,'(\\d+)$',1)::int book_key, rating::double rating, CAST(review_time AS timestamp) review_ts FROM review_db.review")
print('fallback years', fallbacks)
print('pub year parsed with fallback', con.execute('SELECT count(*) FROM b WHERE pub_year IS NOT NULL').fetchone()[0])
for row in con.execute('''SELECT decade_start||'s', count(distinct book_key), count(*), avg(rating) FROM b JOIN r USING(book_key) WHERE pub_year IS NOT NULL GROUP BY decade_start HAVING count(distinct book_key)>=10 ORDER BY avg(rating) DESC''').fetchall(): print(row)
